const totals = $('Get weekly totals').first().json;
const top = $('Get top 3 posts').all().map((item) => item.json);

const n = (value) => Number(value ?? 0).toLocaleString('en-US');
const delta = (pct) =>
  pct === null || pct === undefined ? '' : ` (${pct >= 0 ? '+' : ''}${Number(pct).toFixed(1)}%)`;
const d = totals.deltas ?? {};

const lines = [
  '*Social media, last 7 days*',
  `Posts published: ${n(totals.total_posts)}${delta(d.posts)}`,
  `Impressions: ${n(totals.total_impressions)}${delta(d.impressions)}`,
  `Engagement: ${n(totals.total_engagement)}${delta(d.engagement)}`,
  `Followers: ${n(totals.total_followers)}${delta(d.followers)}`,
];

if (top.length > 0) {
  lines.push('', '*Top posts*');
  for (const post of top) {
    const label = (post.preview || 'Untitled post').slice(0, 80);
    const link = post.permalink ? `<${post.permalink}|${label}>` : label;
    lines.push(`${post.rank}. ${link} · ${n(post.metrics?.engagements)} engagements`);
  }
}

return [{ json: { text: lines.join('\n') } }];
